type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Specification assumptions and guarantees
    //
    // - shape.len() == 2
    // - shape[0] and shape[1] are positive (non-zero)
    // - a.len() == r or a.len() == c, where r = shape[0], c = shape[1]
    //
    // If length of `a` equals r, `a` is treated as a column vector,
    // and the returned matrix repeats each element of `a` in a row.
    //
    // If length of `a` equals c, `a` is treated as a row vector,
    // and the returned matrix repeats `a` in each row.
    //
    // Ensures that the returned matrix has size r x c,
    // and is a broadcast of `a` as described.

    // Verus requires and ensures
    verus::requires(shape.len() == 2);
    verus::requires(shape[0] > 0);
    verus::requires(shape[1] > 0);

    let r = shape[0] as usize;
    let c = shape[1] as usize;

    let len = a.len();

    verus::requires(len == r || len == c);

    if len == r {
        // a is column vector
        // ensures the matrix is r x c,
        // matrix[i][j] = a[i] for all i,j
        let m: Matrix<i8> = (0..r).map(|i| vec![a[i]; c]).collect();

        verus::ensures(m.len() == r);
        verus::ensures(m.iter().all(|row| row.len() == c));
        for i in 0..r {
            for j in 0..c {
                verus::assert(m[i][j] == a[i]);
            }
        }

        m
    } else {
        // a is row vector (len == c)
        // ensures the matrix is r x c,
        // matrix[i][j] = a[j] for all i,j
        let m: Matrix<i8> = (0..r).map(|_| a.clone()).collect();

        verus::ensures(m.len() == r);
        verus::ensures(m.iter().all(|row| row.len() == c));
        for i in 0..r {
            for j in 0..c {
                verus::assert(m[i][j] == a[j]);
            }
        }

        m
    }
}